tool.command:
#import re
@SET_TYPE@
#set $name = re.sub(r'[^\w .\-]', '_', str($input.element_identifier))
## bioheaders exits 1 both when the check fails and when the file cannot be read;
## the messages tell them apart. The status is kept so that the report can be written.
#if $type in ['yaml', 'json', 'jsonld']
    #set $check = 'metadata validated against the schema'
    bioheaders validate --from '$type' '$input' > messages.txt 2>&1 && status=0 || status=\$? ;
#else
    #set $check = 'header validated against the schema and checksum verified'
    bioheaders verify --type '$type' '$input' > messages.txt 2>&1 && status=0 || status=\$? ;
#end if
cat messages.txt &&
## An unreadable file (corrupt or truncated gzip, an I/O error) or a crash is not a
## check result: fail the job.
if grep -qE '^Traceback \(most recent call last\):$|^FHR: (Invalid gzip input |\[Errno [0-9]+\] |unexpected error \(|out of memory)' messages.txt; then
    echo 'The file could not be read, so it was not checked; see the messages above.' >&2 ;
    exit 2 ;
fi &&
if [ "\$status" -eq 0 ]; then
    result=PASSED ;
elif [ "\$status" -eq 1 ]; then
    result=FAILED ;
else
    exit "\$status" ;
fi &&
{
    echo "Result: \$result" ;
    echo 'Dataset: $name' ;
    echo 'Check: $check' ;
    echo "Checked with: fair-bioheaders \$(bioheaders --version)" ;
    echo ;
    cat messages.txt ;
} > '$report'
#if $on_failure == 'fail'
    && [ "\$status" -eq 0 ]
#end if
